document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll(".stat-value"),t=()=>{e.forEach(e=>{const n=+e.getAttribute("data-count"),r=+e.innerText,o=n/200;r<n?(e.innerText=Math.ceil(r+o),setTimeout(t,1)):e.innerText=n})},n=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&(t(),n.unobserve(e.target))})},{threshold:.5});document.querySelectorAll(".stat-card").forEach(e=>{n.observe(e)})});